-- L14596/O44 环境漂移垫片 #3(仅 ihui_dev,2026-10-18):
-- 第 325 枚迁移 line 123 `agent_meta_lessons.source_skills text[] → jsonb` 卡在列默认
-- '{}'::text[] 无法自动投 jsonb。摘默认→改型(文件自带 USING to_jsonb)→按 TS 权威
-- (agent-state.ts:92 sourceSkills jsonb default [])补回。

ALTER TABLE "agent_meta_lessons" ALTER COLUMN "source_skills" DROP DEFAULT;
ALTER TABLE "agent_meta_lessons" ALTER COLUMN "source_skills" TYPE jsonb USING to_jsonb("source_skills");
ALTER TABLE "agent_meta_lessons" ALTER COLUMN "source_skills" SET DEFAULT '[]'::jsonb;
